// az — Azərbaycan dili (azerbaijano).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **sən**, nunca *siz*. É a escolha do turco, que veio antes e é parente próximo: aparece na
// terminação de cada verbo ("seç" e não "seçin", "yaz" e não "yazın"), então não há meio-termo.
//
// GÊNERO: NENHUM. O azerbaijano não tem gênero gramatical — nem no "você", nem no "ele/ela" (o), nem
// no verbo. É a primeira língua desde o turco em que a pergunta "onde ela esconde o sexo?" tem a
// resposta "em lugar nenhum".
//
// O I SEM PONTO, como no turco: ı/I e i/İ são DUAS letras. A caixa alta dos rótulos (text-transform)
// só acerta o İ porque o `<html lang>` diz "az"; comparação sem caixa em texto azerbaijano exige
// `toLocaleLowerCase('az')`.
//
// NOME PRÓPRIO COM SUFIXO vai com hífen (Syden-ə, Syden-də), e não com apóstrofo como no turco: é a
// forma das interfaces azerbaijanas para nome estrangeiro, e poupa o apóstrofo, que já sumiu com
// pares inteiros calado (ver a armadilha do hauçá).
//
// NÚMEROS: o substantivo depois do número fica no singular ("5 mesaj"), então o {n} vai direto.
// `Intl.NumberFormat('az')` devolve `1.234.567` — latinos.
//
// O DETECTOR DO TESTE DE IDIOMAS: o azerbaijano escreve ç, como o português. O detector por letra não
// serve; vai o das chaves, como o vietnamita.
//
// VOCABULÁRIO, decidido uma vez: comunidade = icma, canal = kanal, sala de voz = səs otağı, chamada =
// zəng, conversa = söhbət, mensagem = mesaj, senha = şifrə, lixeira = zibil qutusu, tópico = mövzu,
// conta = hesab, administrador = admin, dono = sahib, cargo = rol, convite = dəvət, perfil = profil,
// transmissão = yayım, recado = səsli mesaj, soundboard = səs paneli, vila = kənd, guarda-roupa =
// qarderob, denúncia = şikayət, tela = ekran.
//
// SELO E INSÍGNIA SEPARADOS: selo = möhür (o da comunidade), insígnia = nişan (a da pessoa).

