  'Festa dos coelhos': 'Dovşan şənliyi',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Beş raund sürətli oyun, hər kəs öz ekranında: refleks, nişançılıq, yaddaş və göz. Hər raundda ən yaxşı olan daha çox xal qazanır.',
  'Saque rápido': 'Cəld atəş',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Siqnalı gözlə və bacardığın qədər tez bas. Siqnaldan əvvəl bassan, oyundan çıxırsan.',
  'Medidor de força': 'Güc ölçən',
  'Pare a barra o mais perto possível de 100%.': 'Zolağı 100%-ə mümkün qədər yaxın dayandır.',
  'Parar o relógio': 'Saatı dayandır',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Saatı düz 10 saniyədə dayandır. Rəqəmlər 3-dən sonra yox olur.',
  'Jogo dos copos': 'Stəkan oyunu',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Kökün harada olduğuna bax və stəkanı izlə. Nə qədər tez tapsan, bir o qədər çox xal.',
  'Siga o coelho': 'Dovşanı izlə',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Oxları ardıcıllıqla təkrarla. Hər düzgün cavabda daha biri gəlir.',
  'Tiro ao alvo': 'Hədəfə atəş',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'Çıxan hədəfləri vur. Hər biri bir xaldır.',
  'Cedo demais!': 'Çox tez!',
