  'A subida está andando.': 'Dırmanış artıq gedir.',
  'A subida não está andando.': 'Dırmanış getmir.',
  'Você não está nesta subida.': 'Sən bu dırmanışda deyilsən.',
  'Pulo do balanço': 'Yelləncəkdən tullanma',
  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'Yelləncəkdən yarpağa tullan. Yarpaq nə qədər uzaqdırsa, bir o qədər çox dəyər.',
  'Barraca de tiro': 'Atıcılıq köşkü',
  'Acerte os corvos que passarem. No coelhinho, não!': 'Uçub keçən qarğaları vur. Dovşancığı yox!',
  'Brasas da fogueira': 'Tonqal közləri',
  'Desvie das brasas. São só três corações!': 'Közlərdən yayın. Cəmi üç ürək var!',
  'Cabo de guerra': 'Kəndir dartma',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Kəndiri dartmaq üçün çıxan oxu bas. Səhv etsən, ilişib qalırsan!',
  'Canteiro que encolhe': 'Kiçilən lək',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Başqalarını ləkdən itələ. Yanıb-sönən kənar uçacaq!',
  'Corrida de cavalinho': 'Taxta at yarışı',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': '← və → düymələrini ritmlə növbələ. Çox tələssən, nəfəsin kəsilər.',
  'Cartas do celeiro': 'Anbar kartları',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'Növbən gələndə bir kart aç və ya kökləri saxla. Tülkü hamısını aparır!',
  'Chuva de cenouras': 'Kök yağışı',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Kökləri yığaraq aşağı en. Daşlardan qaç!',
  'De galho em galho': 'Budaqdan budağa',
  'Solte o cipó quando ele estiver na faixa clara.': 'Sarmaşığı açıq zolaqda olanda burax.',
  'Colheita em dupla': 'Cüt məhsul yığımı',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'Cüt halda: budaqdakı yetişmiş çiyələkləri salır, aşağıdakı onları səbətlə tutur.',
  'Baile da toca': 'Yuvada bal',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Rəqsin sırasını yadda saxla. Sonda işarələnmiş lampada kimin rəqs etdiyini de.',
  'Chão que desmorona': 'Uçan döşəmə',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'Kimsə üstündə dayananda taxta çatlayır. Yeriməyə davam et və başqalarını suya itələ!',
  'Arrume a despensa': 'Kileri səliqəyə sal',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Hər bankanın harada durduğunu yadda saxla və hamısını yerinə qoy.',
  'Esconde-esconde na horta': 'Bostanda gizlənpaç',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Fənərin baxmayacağı yerdə gizlən. Fənər kimdədirsə, o axtarır!',
  'Três flechas': 'Üç ox',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'Ox düz yuxarı qalxır və qarşısına çıxanı deşir. Kiçik şarlar daha çox dəyər.',
  'Bate quando der a flor': 'Çiçəyi görəndə vur',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Çərçivədəki ilə eyni çiçək çıxanda vur. Səhv şəkildə oyundan çıxırsan.',
  'Foguete de cenoura': 'Kök raketi',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Halqa yananda nasosu bas. Ritmdən kənar olsa, hava çıxır.',
  'Pegue a galinha': 'Toyuğu tut',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Toyuğu küncə sıx. Yorulanda yavaşıyır.',
  'Repolhos no gelo': 'Buz üstündə kələmlər',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Buz üstündəki kökləri yığ və kələmlərdən qaç.',
  'Abóboras ladeira abaixo': 'Enişdən aşağı balqabaqlar',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Yuxarıdan balqabaqlar yuvarlanır; dırmanan onlardan yayınmaq üçün zolağını dəyişir!',
  'Quem está atrás da turma?': 'İzdihamın arxasında kim var?',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Kimin gizləndiyini tap. Tək şansın var: nə qədər tez, bir o qədər çox dəyər.',
  'Arremesso do nabo': 'Şalğam atma',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Şalğam meydana tərəf baxanda burax. Nə qədər sürətlə fırlanırsa, bir o qədər uzağa gedir.',
  'Onda no açude': 'Gölməçədə dalğa',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'Avardakı dalğa göndərir; saldakı vaxtında tullanır!',
  'Pula o ponteiro': 'Əqrəbin üstündən tullan',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Əqrəb keçəndə tullan. Getdikcə sürətlənir.',
  'Ponte do riacho': 'Çay körpüsü',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Üç taxtanı körpüyə qədər apar. Batan daşlardan ehtiyatlı ol!',
  'Quem está em qual toca?': 'Kim hansı yuvadadır?',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Heyvanları yuvadan yuvaya izlə. Sonda buludcuqdakının harada olduğunu göstər.',
  'As chaves da porteira': 'Darvazanın açarları',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Bir qızıl kök götür və darvazaya apar. Biri çatmır: daşıyanı itələ!',
  'Destampe os potes': 'Bankaları aç',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Hər qapağı tez oxun tərəfinə fırla. Yanlış tərəf onu yenidən bərkidir.',
  'Praga na toca': 'Yuvada zərərvericilər',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Yuvalardan çıxan tırtılları vur. Dovşancığı yox!',
  'Rebater o rabanete': 'Turpu geri vur',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'Turp bazaya çatanda vur. Düz vaxtında vursan, daha uzağa gedir.',
  'Regar a horta': 'Bostanı sula',
  'Leve a nuvem até o canteiro com sede.': 'Buludu susuz ləkə apar.',
  'Qual destes cresce debaixo da terra?': 'Bunlardan hansı torpağın altında bitir?',
  'Quantas orelhas tem um coelho?': 'Dovşanın neçə qulağı var?',
  'Duas': 'İki',
  'Três': 'Üç',
  'Quatro': 'Dörd',
  'O que o mascote do Syden veste?': 'Syden-in maskotu nə geyinir?',
  'Armadura': 'Zireh',
  'Terno': 'Kostyum',
  'Moletom': 'Kapüşonlu sviter',
