  'Escolha a resposta certa antes que o tempo acabe.': 'Vaxt bitməmiş düzgün cavabı seç.',
  'Balsa a dois': 'İki nəfərlik sal',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Hər kəs öz tərəfindən avar çəkir: avar zərbəsi salı o biri tərəfə itələyir. Birlikdə sal irəli gedir. Kökləri yığın!',
