  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Hər zolağı portret yerinə düşəcək kimi, yuxarıdan aşağı dayandır.',
  'Revezamento do riacho': 'Çayda estafet',
  'Reme alternando ◀ e ▶ quando o remo estiver com você.': 'Avar səndə olanda ◀ və ▶ düymələrini növbələyərək avar çək.',
  'Fuga do rio': 'Çaydan qaçış',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Üzmək üçün dayanmadan bas. Kötük gələndə suya dal!',
  'Roda da feira': 'Yarmarka çarxı',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Çarxın tormozlaması üçün bas. Dayanmazdan əvvəl həmişə bir az sürüşür.',
  'Uma tacada só': 'Tək zərbə',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'Əvvəl nişanı, sonra gücü sabitlə. Yuvaya ən yaxın dayanan qalib gəlir.',
  'Tambor da turma': 'Dəstənin təbili',
  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Dinlə, zərbəni eyni ritmlə təkrarla və sonuna bir zərbə əlavə et.',
  'Torta de cenoura': 'Kök piroqu',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Piroqu cütünlə birlikdə ◀ və ▶ düymələrini növbələyərək ye. İlk qurtaran qalib gəlir!',
  'Trinca da horta': 'Bostan üçlüyü',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Üç barabanı eyni şəkildə dayandır. Hər üçlük bir xal dəyər.',
  'Vidas': 'Canlar',
  'Cenoura teleguiada': 'İdarə olunan kök',
  'Pronta': 'Hazırdır',
  'No ar': 'Havada',
  'Frear': 'Tormoz',
  'Caiu! Agora é torcer de longe.': 'Səni vurub saldılar! İndi uzaqdan azarkeşlik et.',
  'Segure e solte: cenoura teleguiada': 'Basıb saxla və burax: idarə olunan kök',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'İki zərbəyə dözürsən; üçüncüsü yerə salır. Hasarın yanında kəskin dönüş bir anlıq qoruyur.',
  'Acertos: {n}': 'Zərbələr: {n}',
  'Pilotar (para trás, freia e dá ré)': 'İdarə et (geri tormoz edir və geri gedir)',
  'O barco desliza: tire o pé antes da curva. As argolas laranja dão um empurrão.': 'Qayıq sürüşür: döngədən əvvəl qazı burax. Narıncı halqalar təkan verir.',
  'A toupeira-rei caiu!': 'Kral köstəbək yıxıldı!',
  'A turma caiu.': 'Dəstə yıxıldı.',
  'Dano da turma: {n}': 'Dəstənin zərəri: {n}',
  'Sem vidas: agora é torcer pela turma.': 'Can qalmadı: indi dəstəyə azarkeşlik et.',
  'Fase {n} de {total}': 'Mərhələ {n} / {total}',
  'Torrão na mão!': 'Kəsək əldə!',
  'Bomba de semente pronta': 'Toxum bombası hazırdır',
  'Atirar o torrão': 'Kəsəyi at',
  'Bomba de semente': 'Toxum bombası',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Yerdəki işarələrdən qaç. Göyümtül kəsəyi götürmək üçün üstündən keç və onu köstəbəyə geri at; toxum bombası hər mərhələdə birdir.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Flügerə qədər dırman. Düşən əşyalar və qarğalar səni son mərtəbəyə qaytarır.',
  'Subir contra': 'Rəqiblər',
  'Nenhum amigo subiu esta torre ainda.': 'Hələ heç bir dost bu qülləyə dırmanmayıb.',
  'Escolher a torre': 'Qülləni seç',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'Açanda bu dırmanış artıq başlamışdı: sən izləyirsən.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Taxtalar, tayalar və hərəkət edən tirlər üzərindən anbarın ən yuxarısındakı flügerə qədər dırman, düşən alətlərdən və qarğalardan yayın. Tək rejimdə saata və dostların kabuslarına qarşı.',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Kiçik təyyarələrdəki dovşanlar bostanın üstündə noxud və bir-bir idarə olunan kök atırlar. İki zərbəyə dözmək olar; üçüncüsü yerə salır. Havada sonuncu qalan qalib gəlir.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Bütün dəstə üç mərhələdə yuvalardan çıxan kral köstəbəyə qarşı. Yerdəki işarələrdən qaç, göyümtül kəsəkləri götür və geri at. Ya dəstə qalib gəlir, ya da heç kim.',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Göldə, çayda və manqrovda qayıq yarışı. Su sürüşür: döngədən əvvəl qazı burax, sahildən ehtiyatlı ol, axından və halqalardan istifadə et. Tək rejimdə saata və dostların kabuslarına qarşı.',
