  '{n} voltas': 'Dövrə: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Enerji həm can, həm turbodur: kənara dəymək onu xərcləyir, çəhrayı zolaq doldurur.',
  'A nave explodiu: a energia acabou.': 'Gəmi partladı: enerji bitdi.',
  'Posição: {posicao} de {total}': 'Mövqe: {posicao} / {total}',
  'Escolher a pista': 'Trası seç',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Asma trasda yerkökü gəmilərinin yarışı, kartdan qat-qat sürətli. Enerji həm can, həm turbodur: kənara dəymək onu xərcləyir, çəhrayı zolaq doldurur, trasdan çıxmaq isə yıxılmaq deməkdir. Tək rejimdə saata və dostların kabuslarına qarşı.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Qapalı arenada kartlar, hər birində üç şar. Qutuları topla və əşyalarla başqalarının şarlarını partlat: şarı qalmayan oyundan çıxır, sona qalan qalib gəlir.',
  'Esquadrilha da toca': 'Yuvanın eskadrilyası',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Kök təyyarəcikləri bostan zərərvericilərinə qarşı: toxumlardan yayın, gücləndiriciləri götür və sonda mexaniki müqəvvanı vur. Komanda eyni dalğalarda uçur, eskadrilyanın xalları toplanır.',
  'O espantalho caiu!': 'Müqəvva yıxıldı!',
  'A praga venceu desta vez.': 'Bu dəfə zərərvericilər qalib gəldi.',
