  'Os navios não podem encostar um no outro.': 'Gəmilər bir-birinə toxuna bilməz.',
  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Səkkiz 3D dəlik, enişlər, qala və yel dəyirmanı ilə, hamı eyni vaxtda eyni dəliyi oynayır. Nişan almaq və güc vermək üçün sürüşdür və burax. Cəmi ən az zərbə vuran qalib gəlir.',
  'Ver o buraco de cima': 'Dəliyə yuxarıdan bax',
  'Fora da pista! Mais uma tacada.': 'Yoldan çıxdı! Bir zərbə artıq.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Nişan almaq üçün yana, güc üçün aşağı sürüşdür və burax. Klaviaturada: oxlarla nişan alırsan, basılı saxlanan Boşluq isə güc verir.',
  'Futebol dos coelhos': 'Dovşanların futbolu',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Kiçik meydanda futbol, yuxarıdan görünüş. Topu aparmaq üçün ona toxun, daha güclü vurmaq üçün Boşluğu basılı saxla və X ilə ötür. Otaqda komandalar robotlarla tamamlanır.',
  'Quantos por time?': 'Komandada neçə nəfər?',
