  'Partida inválida.': 'Etibarsız oyun.',
  'Ninguém para jogar.': 'Oynamağa heç kim yoxdur.',
  'Caça às pragas da horta': 'Bostan zərərvericiləri ovu',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Qarğalar və çəyirtkələr bostana hücum edir. Qaçmadan vurmaq üçün nişan al və kliklə: sursat sayılıdır, hər dalğa daha sürətli gəlir. Ən çox xal toplayan qalib gəlir.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Zərərvericilər qaçmadan nişan al və kliklə. Hər atış bir yerkökü aparır.',
