  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Qaçmaq üçün oxlar, tullanmaq üçün Boşluq (daha yuxarı qalxmaq üçün basılı saxla).',
  'Nenhum amigo jogou esta fase ainda.': 'Hələ heç bir dost bu mərhələni oynamayıb.',
