  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Adam çatmadı: oyun vaxtından əvvəl, kuboksuz bitdi.',
  'Saiu antes do fim': 'Sondan əvvəl çıxdı',
  'Jogar o dado': 'Zər at',
  '{nome} comprou a cenoura dourada!': '{nome} qızıl kökü aldı!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Qızıl kökü {preco} kökə almaq?',
  'Comprar': 'Al',
  '{nome} chegou à cenoura dourada.': '{nome} qızıl kökə çatdı.',
  'Quantas rodadas?': 'Neçə raund?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Dovşanlar bostanı tülkülərdən, qarğalardan və bir porsuqdan qoruyur. Birlikdə irəliləyin, kombo ilə vurun və bir-birinizə göz olun: 1–4 nəfər.',
  'Pulo do coelho': 'Dovşan tullanması',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Platforma yarışı: qaç, tullan və yıxılma. Təkbaşına, saata və dostlarının xəyalətlərinə qarşı; dəstə ilə, canlı, bir mərhələdə və ya hər üçündə.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Yan-yana iki tərəvəzin yerini dəyiş ki, üç və ya daha çox eyni tərəvəz bir yerə gəlsin. Yığın dayanmadan qalxır: zirvəyə çatmağa qoyma. Dəstə ilə zəncirlər və kombolar başqalarına qutu göndərir.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Altı minigolf çuxuru, hamı eyni vaxtda eyni çuxuru oynayır. Zərbə vurmaq üçün topu geri çək və burax. Ən az zərbə toplayan qalib gəlir.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Hər kəs öz növbəsində zər atır və bostanda irəliləyir. Qızıl kökü almaq üçün kök topla, hər raunddan sonra isə dəstə mini oyun oynayır. Ən çox qızıl kökü olan qalib gəlir.',
