  'Batalha naval': 'Dəniz döyüşü',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Adi domino, 2–4 nəfərlik (4 nəfər olsa, cüt-cüt). Daşları zəncirin uclarına birləşdir, kim birinci bitirsə, digərlərinin əlindəki xalları alır.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Paulista truco oyunu, açıq kart və kozırlarla, 2 nəfər və ya 4 nəfər cüt-cüt. Truco elan et, altıya, doqquza və on ikiyə qaldır, ya da qaç. 12 xal toplayan qalib gəlir.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Braziliya daması: vurmaq məcburidir, irəli də, geri də, dama isə bütün diaqonal boyu gedir. Otaq izləyir.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Hər kəs öz donanmasını gizlədir və digərinin dənizinə atəş açır. Vurdunsa, yenə atırsan. Bütün donanmanı birinci batıran qalib gəlir. Otaq izləyir.',
