  'Cozinha da toca': 'Yuvanın mətbəxi',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Tərkibləri qutulardan götür, taxtada doğra, yandırmadan sobada və peçdə bişir, boşqaba qoy və pəncərədən təhvil ver. Hamı eyni sifarişləri alır: 3 dəqiqədə ən çox boşqab təhvil verən qalib gəlir.',
