  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'Avtomobilləri toqquşdurmadan kəsişmədən buraxmaq üçün bir dəqiqə. Dolu növbə də xala başa gəlir.',
