  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Kompüterində edilən səs və kamera effektləri, serverə heç nə göndərmədən.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Kök Komandosu",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Dəstə ilə qaç və atəş aç: kökatan səkkiz istiqamətə nişan alır, qumbara yol açır, qəfəsdəki balaca dovşanları azad edən gücləndirmə qazanır. Sonda əjdaha gözləyir: 1-dən 4 nəfərədək.",
  'Andar e mirar': "Get və nişan al",
  'Granada': "Qumbara",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Yuva zindanı",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Göbələk kralının yuvasından birlikdə keçin: heyvanlarla dolu otaqlar, gedib-qayıdan kökü olan sandıq, eyni anda iki nəfər istəyən düymələr və kilidli qapı. 1-dən 4 nəfərə qədər.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Yuva rinqi",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Kompüterin üç rəqibinə qarşı refleks boksu. Hər zərbənin xəbərdarlığını oxu, yayın və ya müdafiə et, boşluqda vur. Əlcək parıldayanda vurmaq güclü zərbənin ulduzunu doldurur.",
  'Esquivar': "Yayın",
  'Abaixar e defender': "Əyil və müdafiə et",
  'Socar': "Vur",
  'Soco forte': "Güclü zərbə",
  'Aperte os socos para levantar!': "Qalxmaq üçün zərbə düymələrini bas!",
  'Lutas vencidas: {n}': "Qazanılan döyüşlər: {n}",
  'Nocaute!': "Nokaut!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Ulduz Yolu",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Gəmilərdəki dovşanlar planetin səthində və kosmosda: atəş aç, hədəfi kilidləmək üçün atəşi saxla, mərmiləri yayındırmaq üçün fırlan və ayrıcda yolu seç. Komanda eyni yolla uçur, başçı isə sonda gözləyir.",
  'Pirueta': "Fırlan",
  'Segure para travar a mira': "Hədəfi kilidləmək üçün saxla",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Bostan pinbolu",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Bostanda pinbol masası: yayı saxla, kələmlərdən sıçra və dovşanın yuvasını yandırmaq üçün üç kökü yıx, o da əlavə top buraxır. Üç top var, həddindən çox silkələmək masanı kilidləyir.",
