  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Gecə qurdadamların kimə hücum etdiyini gör. Bir iksir o adamı xilas edir, digəri kimisə oyundan çıxarır; hər biri bir dəfə işləyir.",
