  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Heç kimin almadığı şəhər hərraca çıxır. Şəhəri girov qoymaq pul gətirir, amma o, kirayə yığmır.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "İpucu gediləcək fiquru işıqlandırır. İpucu ilə həll edilən tapmaca xal gətirmir; yarışda ipucu 10 saniyə aparır.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Kozır açıq kartdan sonrakı dəyərdir və hamısını udur. Öz aralarında: ♦, ♠, ♥ və ♣, yəni zap.",
