  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Zərlə irəlilə və dayandığın paytaxtı al. Başqasının şəhərində dayanan kirayə ödəyir.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Hər sətirdə, sütunda və 3 × 3 blokda 1-dən 9-a qədər rəqəmlər təkrarlanmadan olur.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Hər kəs 3 kart alır. 3 raunddan 2-ni udan əli götürür.",
  "Campeonato": "Çempionat",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "11 xalda cüt kartlara baxır və on bir əlini oynayıb-oynamamağa qərar verir. 12-yə çatan qalib gəlir.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Bütün region səndədirsə, 4 binaya qədər tik: hər biri ilə kirayə artır.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Güclü zərbə (★) bütün ulduzları birdən xərcləyir və daha ağrılı olur.",
