  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Gizli bir heyvan seçilir və hər kəs başqalarını təxmin edir. Hər təxmin gizli heyvanla nəyin üst-üstə düşdüyünü göstərir: sinif, qidalanma, harada yaşadığı və çəki. Daha az təxminlə tapan daha çox xal qazanır.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Gizli bir dinozavr seçilir və hər kəs başqalarını təxmin edir. Hər təxmin gizli dinozavrla nəyin üst-üstə düşdüyünü göstərir: dövr, qidalanma, qrup, uzunluq və harada tapıldığı. Daha az təxminlə tapan daha çox xal qazanır.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Gizli bir kimyəvi element seçilir və hər kəs başqalarını təxmin edir. Hər təxmin gizli elementlə nəyin üst-üstə düşdüyünü göstərir: ailə, aqreqat halı, dövr, qrup və atom nömrəsi. Daha az təxminlə tapan daha çox xal qazanır.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Braziliyanın gizli bir ştatı seçilir və hər kəs başqalarını təxmin edir. Hər təxmin gizli ştata qədər məsafəni və istiqaməti, regionu, əhalini, sahəni, sahili və başqa ölkə ilə sərhədi göstərir. Daha az təxminlə tapan daha çox xal qazanır.",
  "Saturno": "Saturn",
